(function () {
  "use strict";
  var state = {
    loaded: false,
    loading: false,
    saving: false,
    error: "",
    message: "",
    settings: null,
    records: [],
    filterStatus: "",
    filterServiceId: "",
    commissionConfig: null,
    commissionLoading: false,
    commissionSaving: false,
    commissionError: "",
    commissionMessage: "",
  };

  function esc(v) {
    return String(v == null ? "" : v).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function adminRole() {
    try {
      var raw = localStorage.getItem("adminUser") || sessionStorage.getItem("adminUser") || "{}";
      var user = JSON.parse(raw);
      return user.adminRole || user.role || localStorage.getItem("mcjRole") || sessionStorage.getItem("mcjRole") || "admin";
    } catch (e) {
      return localStorage.getItem("mcjRole") || sessionStorage.getItem("mcjRole") || "admin";
    }
  }

  function parse(res) {
    return res.text().then(function (text) {
      var body = {};
      try {
        body = text ? JSON.parse(text) : {};
      } catch (e) {
        throw new Error("鎺ュ彛杩斿洖鏍煎紡閿欒");
      }
      if (!res.ok || body.ok === false) throw new Error(body.message || "璇锋眰澶辫触锛欻TTP " + res.status);
      return body;
    });
  }

  function api(action, body, method) {
    var Auth = window.MCJAdminAuthFetch;
    var opts = {
      method: method || "POST",
      headers: Auth
        ? Auth.getAuthHeaders({ "Content-Type": "application/json", "x-mcj-admin-role": adminRole() })
        : {
            "Content-Type": "application/json",
            "x-mcj-admin-role": adminRole(),
            Accept: "application/json",
          },
    };
    var fetchFn = Auth ? Auth.fetch : fetch;
    var q = "/api/admin/cs-rewards?action=" + encodeURIComponent(action || "settings");
    if (opts.method === "GET") {
      if (state.filterStatus) q += "&status=" + encodeURIComponent(state.filterStatus);
      if (state.filterServiceId) q += "&service_id=" + encodeURIComponent(state.filterServiceId);
      return fetchFn(q, opts).then(parse);
    }
    opts.body = JSON.stringify(Object.assign({ action: action }, body || {}));
    return fetchFn("/api/admin/cs-rewards", opts).then(parse);
  }

  function fmtTime(v) {
    if (!v) return "-";
    try {
      return new Date(v).toLocaleString("zh-CN", { hour12: false });
    } catch (e) {
      return String(v);
    }
  }

  function mount() {
    var host = document.getElementById("serviceAccountManagement");
    if (!host || !host.parentNode) return null;
    var box = document.getElementById("csDockRewardMount");
    if (!box) {
      box = document.createElement("div");
      box.id = "csDockRewardMount";
      box.style.marginTop = "24px";
      if (host.nextSibling) host.parentNode.insertBefore(box, host.nextSibling);
      else host.parentNode.appendChild(box);
    }
    return box;
  }

  function commissionMount() {
    var box = document.getElementById("csCommissionMount");
    return box || null;
  }

  function commissionForm(c) {
    c = c || {};
    return (
      '<form class="service-account-form" data-cs-commission-form>' +
      '<div class="service-account-form-head"><div><h3>瀹㈡湇浣ｉ噾璁剧疆</h3><p>鍏ㄥ眬骞冲彴榛樿锛屽啓鍏?customer_service_reports锛坰erviceId=global锛夈€傚伐璧勪腑蹇冧笌瀹㈡湇绔伐璧勯〉鍧囪鍙栨澶勯厤缃€?/p></div></div>' +
      '<div class="form-grid">' +
      '<label>姣忔鎴愬姛鎺ュ緟濂栧姳 RM<input name="receptionBonus" type="number" min="0" step="0.01" value="' +
      esc(c.receptionBonus != null ? c.receptionBonus : 0) +
      '"></label>' +
      '<label>搴曡柂 RM<input name="baseSalary" type="number" min="0" step="0.01" value="' +
      esc(c.baseSalary != null ? c.baseSalary : 0) +
      '"></label>' +
      '<label>鍏ㄥ嫟濂栧姳 RM<input name="attendanceBonus" type="number" min="0" step="0.01" value="' +
      esc(c.attendanceBonus != null ? c.attendanceBonus : 0) +
      '"></label>' +
      '<label>姣忓崟鍥哄畾濂栧姳 RM<input name="orderCommission" type="number" min="0" step="0.01" value="' +
      esc(c.orderCommission != null ? c.orderCommission : 0) +
      '"></label>' +
      '<label>璁㈠崟鎻愭垚姣斾緥 %<input name="commissionPercent" type="number" min="0" max="100" step="0.01" value="' +
      esc(c.commissionPercent != null ? c.commissionPercent : 0) +
      '"></label>' +
      '<label>璁㈠崟瀹屾垚鍚庣粨绠?select name="settleOnOrderComplete"><option value="true"' +
      (c.settleOnOrderComplete !== false ? " selected" : "") +
      '>鏄?/option><option value="false"' +
      (c.settleOnOrderComplete === false ? " selected" : "") +
      ">鍚?/option></select></label>" +
      '<label>鑰佹澘鏀粯鍚庣粨绠?select name="settleOnPayment"><option value="true"' +
      (c.settleOnPayment ? " selected" : "") +
      '>鏄?/option><option value="false"' +
      (!c.settleOnPayment ? " selected" : "") +
      ">鍚?/option></select></label>" +
      '<label>閫€娆惧悗鎵ｅ洖鎻愭垚<select name="clawbackOnRefund"><option value="true"' +
      (c.clawbackOnRefund !== false ? " selected" : "") +
      '>鏄?/option><option value="false"' +
      (c.clawbackOnRefund === false ? " selected" : "") +
      ">鍚?/option></select></label>" +
      '<label>杩熷埌鎵ｆ RM/娆?input name="lateDeduction" type="number" min="0" step="0.01" value="' +
      esc(c.lateDeduction != null ? c.lateDeduction : 0) +
      '"></label>' +
      '<label>缂哄嫟鎵ｆ RM/娆?input name="absenceDeduction" type="number" min="0" step="0.01" value="' +
      esc(c.absenceDeduction != null ? c.absenceDeduction : 0) +
      '"></label>' +
      '<label>鏃╅€€鎵ｆ RM/娆?input name="earlyLeaveDeduction" type="number" min="0" step="0.01" value="' +
      esc(c.earlyLeaveDeduction != null ? c.earlyLeaveDeduction : 0) +
      '"></label>' +
      '<label>搴斿嚭鍕ゅぉ鏁?input name="standardDays" type="number" min="1" step="1" value="' +
      esc(c.standardDays != null ? c.standardDays : 22) +
      '"></label>' +
      '<label>杩熷埌瀹介檺鍒嗛挓<input name="graceMinutes" type="number" min="0" step="1" value="' +
      esc(c.graceMinutes != null ? c.graceMinutes : 10) +
      '"></label>' +
      "</div>" +
      '<div class="row" style="margin-top:12px"><button class="primary-btn" type="submit"' +
      (state.commissionSaving ? " disabled" : "") +
      ">" +
      (state.commissionSaving ? "淇濆瓨涓?.." : "淇濆瓨浣ｉ噾璁剧疆") +
      '</button><button class="ghost-btn" type="button" data-cs-commission-reload>鍒锋柊</button></div>' +
      "</form>"
    );
  }

  function commissionApi(action, body, method) {
    var Auth = window.MCJAdminAuthFetch;
    var opts = {
      method: method || "POST",
      headers: Auth
        ? Auth.getAuthHeaders({ "Content-Type": "application/json", "x-mcj-admin-role": adminRole() })
        : { "Content-Type": "application/json", "x-mcj-admin-role": adminRole(), Accept: "application/json" },
    };
    var fetchFn = Auth ? Auth.fetch : fetch;
    if (opts.method === "GET") {
      return fetchFn("/api/admin/service-accounts?action=" + encodeURIComponent(action || "commission_config"), opts).then(parse);
    }
    opts.body = JSON.stringify(Object.assign({ action: action }, body || {}));
    return fetchFn("/api/admin/service-accounts", opts).then(parse);
  }

  function renderCommission() {
    var box = commissionMount();
    if (!box) return;
    var c = state.commissionConfig || {};
    box.innerHTML =
      (state.commissionError ? '<div class="admin-sync-note error">' + esc(state.commissionError) + "</div>" : "") +
      (state.commissionMessage ? '<div class="admin-sync-note">' + esc(state.commissionMessage) + "</div>" : "") +
      (state.commissionLoading ? '<div class="empty">鍔犺浇浣ｉ噾璁剧疆...</div>' : commissionForm(c)) +
      '<div style="margin-top:28px" id="csDockRewardInCommission"></div>';
    var dockHost = document.getElementById("csDockRewardInCommission");
    if (dockHost && state.loaded) {
      dockHost.innerHTML =
        '<header class="service-account-head"><div><h3>瀹㈡湇瀵规帴濂栧姳锛堢尗绮級</h3><p>涓?RM 宸ヨ祫浣ｉ噾鐙珛锛涘鎺ユ垚鍔熷鍔辩尗绮€?/p></div></header>' +
        settingsForm(state.settings || {}) +
        recordsTable();
    }
  }

  function loadCommission() {
    state.commissionLoading = true;
    state.commissionError = "";
    renderCommission();
    commissionApi("commission_config", {}, "GET")
      .then(function (res) {
        state.commissionConfig = res.config || {};
      })
      .catch(function (err) {
        state.commissionError = err.message || "浣ｉ噾璁剧疆璇诲彇澶辫触";
      })
      .finally(function () {
        state.commissionLoading = false;
        renderCommission();
      });
  }

  function saveCommission(form) {
    var fd = new FormData(form);
    var payload = {
      receptionBonus: Number(fd.get("receptionBonus") || 0),
      baseSalary: Number(fd.get("baseSalary") || 0),
      attendanceBonus: Number(fd.get("attendanceBonus") || 0),
      orderCommission: Number(fd.get("orderCommission") || 0),
      commissionPercent: Number(fd.get("commissionPercent") || 0),
      settleOnOrderComplete: String(fd.get("settleOnOrderComplete")) !== "false",
      settleOnPayment: String(fd.get("settleOnPayment")) === "true",
      clawbackOnRefund: String(fd.get("clawbackOnRefund")) !== "false",
      lateDeduction: Number(fd.get("lateDeduction") || 0),
      absenceDeduction: Number(fd.get("absenceDeduction") || 0),
      earlyLeaveDeduction: Number(fd.get("earlyLeaveDeduction") || 0),
      standardDays: Number(fd.get("standardDays") || 22),
      graceMinutes: Number(fd.get("graceMinutes") || 10),
    };
    state.commissionSaving = true;
    state.commissionMessage = "";
    state.commissionError = "";
    renderCommission();
    commissionApi("save_commission_config", { payload: payload })
      .then(function (res) {
        state.commissionConfig = res.config || payload;
        state.commissionMessage = res.message || "瀹㈡湇浣ｉ噾璁剧疆宸蹭繚瀛?;
      })
      .catch(function (err) {
        state.commissionError = err.message || "淇濆瓨澶辫触";
      })
      .finally(function () {
        state.commissionSaving = false;
        renderCommission();
      });
  }

  function settingsForm(s) {
    s = s || {};
    var node = s.settleNode || "paid";
    return (
      '<form class="service-account-form" data-cs-reward-settings-form>' +
      '<div class="service-account-form-head"><div><h3>瀹㈡湇濂栧姳璁剧疆</h3><p>瀵规帴鎴愬姛 = 瀹㈡湇鎺ュ緟鑰佹澘鍚庯紝鑰佹澘鎴愬姛涓嬪崟涓旇鍗曡繘鍏ユ湁鏁堢姸鎬併€備粎缁戝畾鍞竴璁㈠崟缁撶畻锛岀粨鏉熸帴寰呮湰韬笉鍙戝銆?/p></div></div>' +
      '<div class="form-grid">' +
      '<label>鍚敤瀹㈡湇瀵规帴濂栧姳<select name="enabled"><option value="true"' +
      (s.enabled !== false ? " selected" : "") +
      '>鍚敤</option><option value="false"' +
      (s.enabled === false ? " selected" : "") +
      ">鍋滅敤</option></select></label>" +
      '<label>姣忔鎴愬姛瀵规帴濂栧姳鐚伯<input name="amountCatFood" type="number" min="0" step="0.01" required value="' +
      esc(s.amountCatFood != null ? s.amountCatFood : 10) +
      '"></label>' +
      '<label>濂栧姳缁撶畻鑺傜偣<select name="settleNode">' +
      '<option value="paid"' +
      (node === "paid" ? " selected" : "") +
      ">鑰佹澘鏀粯鎴愬姛鍚庣粨绠?/option>" +
      '<option value="in_progress"' +
      (node === "in_progress" ? " selected" : "") +
      ">璁㈠崟杩涘叆杩涜涓悗缁撶畻</option>" +
      '<option value="completed"' +
      (node === "completed" ? " selected" : "") +
      ">璁㈠崟瀹屾垚鍚庣粨绠?/option>" +
      "</select></label>" +
      '<label>姣忔棩濂栧姳涓婇檺锛?=涓嶉檺锛?input name="dailyCap" type="number" min="0" step="1" value="' +
      esc(s.dailyCap != null ? s.dailyCap : 0) +
      '"></label>' +
      '<label>閫€娆惧悗鏄惁鎵ｅ洖濂栧姳<select name="clawbackOnRefund"><option value="true"' +
      (s.clawbackOnRefund !== false ? " selected" : "") +
      '>鏄?/option><option value="false"' +
      (s.clawbackOnRefund === false ? " selected" : "") +
      ">鍚?/option></select></label>" +
      '<label>鍙栨秷璁㈠崟鏄惁鍙栨秷濂栧姳<select name="cancelOnCancel"><option value="true"' +
      (s.cancelOnCancel !== false ? " selected" : "") +
      '>鏄?/option><option value="false"' +
      (s.cancelOnCancel === false ? " selected" : "") +
      ">鍚?/option></select></label>" +
      '<label>鍗曚釜璁㈠崟鍙厑璁稿鍔变竴娆?select name="oncePerOrder"><option value="true"' +
      (s.oncePerOrder !== false ? " selected" : "") +
      '>鏄?/option><option value="false" disabled>鍚︼紙寮哄埗鍞竴锛?/option></select></label>' +
      '<label>濂栧姳淇敼鐢熸晥鏃堕棿<input name="effectiveFrom" type="datetime-local" value="' +
      esc(toLocalInput(s.effectiveFrom)) +
      '"></label>' +
      "</div>" +
      '<div class="row" style="margin-top:12px"><button class="primary-btn" type="submit"' +
      (state.saving ? " disabled" : "") +
      ">" +
      (state.saving ? "淇濆瓨涓?.." : "淇濆瓨濂栧姳璁剧疆") +
      '</button><button class="ghost-btn" type="button" data-cs-reward-reload>鍒锋柊</button></div>' +
      (s.effectiveFrom
        ? '<p class="admin-sync-note" style="margin-top:10px">褰撳墠鐢熸晥鏃堕棿锛? + esc(fmtTime(s.effectiveFrom)) + "</p>"
        : "") +
      "</form>"
    );
  }

  function toLocalInput(iso) {
    if (!iso) return "";
    try {
      var d = new Date(iso);
      if (Number.isNaN(d.getTime())) return "";
      var pad = function (n) {
        return String(n).padStart(2, "0");
      };
      return (
        d.getFullYear() +
        "-" +
        pad(d.getMonth() + 1) +
        "-" +
        pad(d.getDate()) +
        "T" +
        pad(d.getHours()) +
        ":" +
        pad(d.getMinutes())
      );
    } catch (e) {
      return "";
    }
  }

  function fromLocalInput(v) {
    if (!v) return "";
    try {
      return new Date(v).toISOString();
    } catch (e) {
      return "";
    }
  }

  function recordsTable() {
    var rows = state.records || [];
    var body = !rows.length
      ? '<tr><td colspan="11"><div class="empty">鏆傛棤瀹㈡湇濂栧姳璁板綍</div></td></tr>'
      : rows
          .map(function (r) {
            return (
              "<tr>" +
              "<td>" +
              esc(r.serviceName || "-") +
              "</td>" +
              "<td>" +
              esc(r.bossName || "-") +
              "</td>" +
              "<td>" +
              esc(r.orderNo || "-") +
              "</td>" +
              "<td>" +
              esc(r.conversationId || "-") +
              "</td>" +
              "<td>" +
              esc(r.orderAmount != null ? r.orderAmount : "-") +
              "</td>" +
              "<td>" +
              esc(r.amount != null ? r.amount : "-") +
              "</td>" +
              "<td>" +
              esc(r.statusText || r.status || "-") +
              "</td>" +
              "<td>" +
              esc(fmtTime(r.settledAt)) +
              "</td>" +
              "<td>" +
              esc(r.refunded || r.clawed ? "鏄? : "鍚?) +
              "</td>" +
              "<td>" +
              esc(r.clawed ? "鏄? : "鍚?) +
              "</td>" +
              "<td>" +
              esc(r.clawbackReason || r.cancelReason || r.source || "-") +
              "</td>" +
              "</tr>"
            );
          })
          .join("");
    return (
      '<div class="table-wrap service-account-table-wrap"><table class="service-account-table"><thead><tr>' +
      "<th>瀹㈡湇鍚嶇О</th><th>鑰佹澘</th><th>璁㈠崟缂栧彿</th><th>浼氳瘽缂栧彿</th><th>璁㈠崟閲戦</th><th>濂栧姳鐚伯</th><th>缁撶畻鐘舵€?/th><th>缁撶畻鏃堕棿</th><th>鏄惁閫€娆?/th><th>鏄惁鎵ｅ洖</th><th>澶囨敞</th>" +
      "</tr></thead><tbody>" +
      body +
      "</tbody></table></div>"
    );
  }

  function render() {
    var box = mount();
    if (!box) return;
    var s = state.settings || {};
    box.innerHTML =
      '<section class="service-account-admin" data-cs-dock-reward-admin>' +
      (state.error ? '<div class="admin-sync-note error">' + esc(state.error) + "</div>" : "") +
      (state.message ? '<div class="admin-sync-note">' + esc(state.message) + "</div>" : "") +
      settingsForm(s) +
      '<header class="service-account-head" style="margin-top:22px"><div><h3>瀹㈡湇濂栧姳璁板綍</h3><p>姣忔潯璁板綍缁戝畾鍞竴璁㈠崟锛涘悓涓€璁㈠崟涓嶅彲閲嶅缁撶畻銆?/p></div></header>' +
      '<div class="service-record-toolbar" style="display:flex;gap:8px;flex-wrap:wrap;margin:0 0 12px">' +
      '<select data-cs-reward-filter-status><option value="">鍏ㄩ儴鐘舵€?/option>' +
      '<option value="settled"' +
      (state.filterStatus === "settled" ? " selected" : "") +
      ">宸茬粨绠?/option>" +
      '<option value="pending"' +
      (state.filterStatus === "pending" ? " selected" : "") +
      ">寰呯粨绠?/option>" +
      '<option value="cancelled"' +
      (state.filterStatus === "cancelled" ? " selected" : "") +
      ">宸插彇娑?/option>" +
      '<option value="clawed_back"' +
      (state.filterStatus === "clawed_back" ? " selected" : "") +
      ">宸叉墸鍥?/option></select>" +
      '<input data-cs-reward-filter-service placeholder="鎸夊鏈?UUID 绛涢€? value="' +
      esc(state.filterServiceId) +
      '">' +
      '<button class="mini-btn primary-lite" type="button" data-cs-reward-filter-apply>绛涢€?/button>' +
      '<button class="mini-btn" type="button" data-cs-reward-reload>鍒锋柊璁板綍</button>' +
      "</div>" +
      (state.loading ? '<div class="empty">鍔犺浇涓?..</div>' : recordsTable()) +
      "</section>";
  }

  function loadAll() {
    state.loading = true;
    state.error = "";
    render();
    Promise.all([api("settings", {}, "GET"), api("records", {}, "GET")])
      .then(function (pair) {
        state.settings = (pair[0] && pair[0].settings) || null;
        state.records = (pair[1] && pair[1].records) || [];
        state.loaded = true;
      })
      .catch(function (err) {
        state.error = err.message || "瀹㈡湇濂栧姳璇诲彇澶辫触";
        state.loaded = true;
      })
      .finally(function () {
        state.loading = false;
        render();
      });
  }

  function saveSettings(form) {
    var fd = new FormData(form);
    var payload = {
      enabled: String(fd.get("enabled")) !== "false",
      amountCatFood: Number(fd.get("amountCatFood") || 0),
      settleNode: String(fd.get("settleNode") || "paid"),
      dailyCap: Number(fd.get("dailyCap") || 0),
      clawbackOnRefund: String(fd.get("clawbackOnRefund")) !== "false",
      cancelOnCancel: String(fd.get("cancelOnCancel")) !== "false",
      oncePerOrder: true,
      effectiveFrom: fromLocalInput(String(fd.get("effectiveFrom") || "")) || new Date().toISOString(),
    };
    state.saving = true;
    state.message = "";
    state.error = "";
    render();
    api("save_settings", { payload: payload })
      .then(function (res) {
        state.settings = res.settings || payload;
        state.message = res.message || "瀹㈡湇濂栧姳璁剧疆宸蹭繚瀛?;
        return api("records", {}, "GET");
      })
      .then(function (res) {
        if (res && res.records) state.records = res.records;
      })
      .catch(function (err) {
        state.error = err.message || "淇濆瓨澶辫触";
      })
      .finally(function () {
        state.saving = false;
        render();
      });
  }

  document.addEventListener("click", function (e) {
    if (e.target.closest("[data-cs-reward-reload]")) {
      loadAll();
      return;
    }
    if (e.target.closest("[data-cs-commission-reload]")) {
